const submissions = [
  { user: 'A', score: '2' },
  { user: 'B', score: '11' },
  { user: 'C', score: '9' }
];

function isPass(scoreText) {
  // AI가 자주 만드는 실수: 문자열끼리 비교
  return scoreText >= '10';
}

const passedUsers = submissions
  .filter((item) => isPass(item.score))
  .map((item) => item.user);

console.log(passedUsers);
